#include "opensim/scene/movement_animation.hpp"
#include <bit>
#include <iostream>
#include <sstream>
#include <stdexcept>
using namespace opensim;using namespace scene;
static std::string h(float f){std::ostringstream s;s<<std::hex<<std::bit_cast<std::uint32_t>(f);return s.str();}
static MovementAnimationContext context(int frame,int mode){MovementAnimationContext c;c.colliding=true;c.use_fly_slow=mode&1;c.always_run=frame==2;c.stop_active=frame==3;
 if(frame>=1&&frame<=3)c.controls=1;if(frame>=4&&frame<=7)c.controls=mode&32?1u<<23:16;if(frame==4&&(mode&2))c.controls|=0x8000;
 if(frame>=8&&frame<=10){c.colliding=false;c.velocity.z=frame==8?2.f:-8.f;}
 if(frame>=14&&frame<=19){c.colliding=false;c.velocity.z=(mode&4096)?-.5f:frame==14?-4.f:(mode&2048)?-10.f:(mode&1024)?-14.f:-20.f;}
 if(frame==21&&(mode&2))c.controls|=0x8000;
 if(frame>=23&&frame<=27){c.flying=true;c.controls=frame==23?1:frame==24?16:frame>=26?32:0;c.colliding=frame==27;}
 if(frame==29)c.controls=33;if(frame==30)c.controls=0x2000000;if(frame==31)c.controls=0x4000000;
 if((mode&4)&&frame%11==0)c.actor_present=false;if((mode&8)&&frame%13==0)c.sit_ground=true;if((mode&16)&&frame%17==0)c.parent_id=5;if((mode&16)&&frame%19==0)c.parent_uuid=framework::Uuid("00112233-4455-6677-8899-aabbccddeeff");if((mode&64)&&frame%7==0)c.in_transit=true;if((mode&256)&&frame>=14&&frame<=19)c.pid_hover_active=true;return c;}
static void probe(int mode,std::int32_t base){std::int32_t clock=base;MovementAnimator animator([&]{return clock;});for(int frame=0;frame<32;frame++){clock=std::bit_cast<std::int32_t>(static_cast<std::uint32_t>(base)+frame*200u);auto c=context(frame,mode);std::string trace;MovementAnimationEffects e;e.jump=[&](float v){trace+="J:"+h(v)+";";};e.set_flying=[&](bool b){trace+="F:"+std::to_string(b)+";";};e.set_selected=[&](bool b){trace+="S:"+std::to_string(b)+";";};e.try_set_animation=[&](const std::string& name){trace+="A:"+name+";";return !(mode&128);};auto r=(mode&512)&&frame%3==0?animator.force_update(c,e):animator.update(c,e);auto s=animator.snapshot();std::cout<<r.animation<<"|"<<int(s.state)<<"|"<<s.is_jumping<<s.falling<<"|"<<s.tick_fall<<","<<s.tick_land<<","<<s.tick_jump<<"|"<<h(s.last_fall_velocity)<<"|"<<c.flying<<"|"<<r.name_changed<<r.apply_attempted<<r.applied<<"|"<<trace<<"\n";}}
int main(int argc,char**){try{if(argc>1){int mode;std::int32_t clock;while(std::cin>>mode>>clock)probe(mode,clock);return 0;}int checks=0;auto test=[&](bool ok,const char* message){if(!ok)throw std::runtime_error(message);checks++;};std::int32_t clock=100;MovementAnimator animator([&]{return clock;});auto c=context(0,0);test(animator.snapshot().animation=="STAND"&&animator.state()==MotionControlState::onsurface,"source constructor defaults");int apply=0,jumps=0;MovementAnimationEffects e;e.try_set_animation=[&](auto){apply++;return true;};e.jump=[&](float force){test(force==9.4f,"source jump constant");jumps++;};auto r=animator.update(c,e);test(!r.apply_attempted&&apply==0,"unchanged update suppresses apply");r=animator.force_update(c,e);test(r.apply_attempted&&r.applied&&apply==1,"force applies unchanged name");c.controls=16;r=animator.update(c,e);test(r.animation=="PREJUMP"&&jumps==0,"prejump effect deferred");clock=549;r=animator.update(c,e);test(r.animation=="PREJUMP"&&jumps==0,"prejump449ms");clock=550;r=animator.update(c,e);test(r.animation=="JUMP"&&jumps==1,"source450ms jump");animator.update(c,e);test(jumps==1,"jump not replayed on same animation");MovementAnimator landing([&]{return clock;});c=context(27,0);bool physics_flying=true;e.set_flying=[&](bool b){physics_flying=b;};r=landing.update(c,e);test(!c.flying&&!physics_flying&&r.animation=="LAND","landing clears actual flying via callback");MovementAnimator nudge([&]{return clock;});c=context(4,32);r=nudge.update(c,e);test(r.animation=="STAND"&&nudge.state()==MotionControlState::onsurface,"nudge up does not jump");std::cout<<"PASS: "<<checks<<" movement animation state/effect checks\n";
 }catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
